patterns.project.review:
:language 1
:title "Project review"
:input topic text
:output plan
!use project.step as plan {
    :with topic
}
!show {
    First step: {{plan.next_step}}
}
-> end

patterns.project.step:
:language 1
:title "Choose a small step"
:input topic text
:output next_step
!ask detail {
    What would you like to try for {{topic}}?
}
!ask next_step {
    What is one small step toward {{detail}}?
}
-> end
